-- 000025_cfop_catalog.sql
--
-- System-wide CFOP catalog + farm-tied CFOPs + per-farm use counters for the
-- detached NF-e (NF-e avulsa) selector.
--
-- * cfop: read-only reference catalog, seeded from the Contabilizei complete
--   CFOP table (https://www.contabilizei.com.br/contabilidade-online/tabela-cfop-completa/)
--   plus the CFOPs already assumed by the system (pkg/nfe/defaults
--   NaturezaOpForCFOP keys and the agriculture defaults 5101/5102/5901/6202).
-- * farm_cfop: farm-registered extra codes. Disjoint from cfop (registration
--   rejects catalog duplicates), visible only to the owning farm.
-- * farm_cfop_use: per-farm use counters feeding the "Mais utilizados" group.
--   Local DB only; never sent to SEFAZ.
--
-- origin_destination is derived from the first digit (1/5 = Mesmo estado,
-- 2/6 = Outro estado, 3/7 = Exterior). The referenced page lists 6905 with
-- "Mesmo estado"; it is seeded as "Outro estado" to match the derivation rule.
--
-- Idempotent: CREATE TABLE IF NOT EXISTS + INSERT ... ON CONFLICT DO NOTHING.

CREATE TABLE IF NOT EXISTS cfop (
    code               TEXT PRIMARY KEY,
    description        TEXT NOT NULL,
    origin_destination TEXT NOT NULL,
    CONSTRAINT cfop_origin_destination_check
        CHECK (origin_destination IN ('Mesmo estado', 'Outro estado', 'Exterior'))
);

CREATE TABLE IF NOT EXISTS farm_cfop (
    farm_id            INTEGER NOT NULL REFERENCES farm(id),
    code               TEXT    NOT NULL,
    description        TEXT    NOT NULL,
    origin_destination TEXT    NOT NULL,
    PRIMARY KEY (farm_id, code),
    CONSTRAINT farm_cfop_origin_destination_check
        CHECK (origin_destination IN ('Mesmo estado', 'Outro estado', 'Exterior'))
);

CREATE TABLE IF NOT EXISTS farm_cfop_use (
    farm_id    INTEGER NOT NULL REFERENCES farm(id),
    code       TEXT    NOT NULL,
    use_count  INTEGER NOT NULL DEFAULT 0,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (farm_id, code)
);

ON CONFLICT (code) DO NOTHING;
